import fs from 'node:fs';
import {spawnSync} from 'node:child_process';
const file = 'src/styles.css';
const original = fs.readFileSync(file, 'utf8');
let depth = 0;
const formatted = original.replace(/\\s*([{};])\\s*/g, (_, token) => {
  if (token === '{') { depth++; return ' {\\n' + '  '.repeat(depth); }
  if (token === '}') { depth = Math.max(0, depth - 1); return '\\n' + '  '.repeat(depth) + '}\\n' + '  '.repeat(depth); }
  return ';\\n' + '  '.repeat(depth);
}).split('\\n').map(line => line.trimEnd()).filter((line, index, lines) => line || lines[index - 1]).join('\\n') + '\\n';
const patch = "'`*** Begin Patch'"\\n*** Update File: "'${file}'"\\n@@\\n"'${original.split('"'\\n').map(line => '-' + line).join('\\n')}\\n"'${formatted.split('"'\\n').map(line => '+' + line).join('\\n')}\\n*** End Patch\\n"'`;
const result = spawnSync('"'apply_patch', [patch], {encoding:'utf8'});
console.log(result.stdout, result.stderr);
